public function is(string $tester)
{
    $tester = trim($tester);

    if (preg_match('/^\d+$/', $tester)) {
        return $this->year === (int) $tester;
    }

    if (preg_match('/^\d{3,}-\d{1,2}$/', $tester)) {
        $function = static::$parseFunction;

        if (!$function) {
            try {
                $monthDate = new static($tester);
            } catch (Exception $exception) {
                $monthDate = @static::now()->change($tester);

                if (!$monthDate) {
                    throw new InvalidFormatException("Could not parse '$tester': ".$exception->getMessage(), 0, $exception);
                }
            }
        } else {
            if (\is_string($function) && method_exists(static::class, $function)) {
                $function = [static::class, $function];
            }

            $monthDate = $function($tester);
        }

        $monthDate = $this->resolveCarbon($monthDate);

        return $this->rawFormat('Y-m') === $monthDate->rawFormat('Y-m');
    }

    if (preg_match('/^\d{1,2}-\d{1,2}$/', $tester)) {
        $dayTester = $this->year.'-'.$tester;
        $function = static::$parseFunction;

        if (!$function) {
            try {
                $dayDate = new static($dayTester);
            } catch (Exception $exception) {
                $dayDate = @static::now()->change($dayTester);

                if (!$dayDate) {
                    throw new InvalidFormatException("Could not parse '$dayTester': ".$exception->getMessage(), 0, $exception);
                }
            }
        } else {
            if (\is_string($function) && method_exists(static::class, $function)) {
                $function = [static::class, $function];
            }

            $dayDate = $function($dayTester);
        }

        $dayDate = $this->resolveCarbon($dayDate);

        return $this->rawFormat('Y-m-d') === $dayDate->rawFormat('Y-m-d');
    }

    $modifier = preg_replace('/(\d)h$/i', '$1:00', $tester);

    /* @var CarbonInterface $max */
    $medianFunction = static::$parseFunction;
    $medianBase = '5555-06-15 12:30:30.555555';

    if (!$medianFunction) {
        try {
            $median = new static($medianBase);
        } catch (Exception $exception) {
            $median = @static::now()->change($medianBase);

            if (!$median) {
                throw new InvalidFormatException("Could not parse '$medianBase': ".$exception->getMessage(), 0, $exception);
            }
        }
    } else {
        if (\is_string($medianFunction) && method_exists(static::class, $medianFunction)) {
            $medianFunction = [static::class, $medianFunction];
        }

        $median = $medianFunction($medianBase);
    }

    $median = $median->modify($modifier);

    if ($this instanceof DateTimeImmutable) {
        $current = $this;
        $other = $this->modify($modifier);
    } else {
        $current = clone $this;
        $other = (clone $this)->modify($modifier);
    }

    /* @var CarbonInterface $other */
    if ($current->eq($other)) {
        return true;
    }

    if (preg_match('/\d:\d{1,2}:\d{1,2}$/', $tester)) {
        $truncated = $current->setTime($current->hour, $current->minute, $current->second, 0);

        return $truncated->eq($other);
    }

    if (preg_match('/\d:\d{1,2}$/', $tester)) {
        return $current->startOfMinute()->eq($other);
    }

    if (preg_match('/\d(h|am|pm)$/', $tester)) {
        return $current->startOfHour()->eq($other);
    }

    if (preg_match(
        '/^(january|february|march|april|may|june|july|august|september|october|november|december)\s+\d+$/i',
        $tester
    )) {
        return $current->startOfMonth()->eq($other->startOfMonth());
    }

    $units = [
        'month' => [1, 'year'],
        'day' => [1, 'month'],
        'hour' => [0, 'day'],
        'minute' => [0, 'hour'],
        'second' => [0, 'minute'],
        'microsecond' => [0, 'second'],
    ];

    foreach ($units as $unit => [$minimum, $startUnit]) {
        if ($minimum === $median->$unit) {
            $normalizedUnit = static::singularUnit($startUnit);

            if ($unit === 'month' || $unit === 'day') {
                if ($unit === 'month') {
                    $aligned = $current->setDate($current->year, 1, 1);
                } else {
                    $aligned = $current->setDate($current->year, $current->month, 1);
                }

                $current = $aligned->startOfDay();
            } else {
                if ($unit === 'hour') {
                    $startMethod = 'startOf'.ucfirst($normalizedUnit);
                    $current = $current->$startMethod();
                } else {
                    $hour = $current->hour;

                    if ($unit === 'minute') {
                        $current = $current->setTime($hour, 0, 0, 0);
                    } else {
                        $minute = $current->minute;

                        if ($unit === 'second') {
                            $current = $current->setTime($hour, $minute, 0, 0);
                        } else {
                            $second = $current->second;
                            $current = $current->setTime($hour, $minute, $second, 0);
                        }
                    }
                }
            }

            break;
        }
    }

    return $current->eq($other);
}

